// Generated from blocks — ZERO1 Smart Board Simulator

#include <Adafruit_NeoPixel.h>

const int BUZZER = 8;  // buzzer
const int TRIG_PIN = 3;  // ultrasonic trigger
const int ECHO_PIN = 2;  // ultrasonic echo
const int RGB_PIN = 9;  // RGB LED (WS2812)

Adafruit_NeoPixel pixels(1, RGB_PIN, NEO_GRB + NEO_KHZ800);

float distance = 0.0;

float readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long duration = pulseIn(ECHO_PIN, HIGH, 30000);
  return duration * 0.0343 / 2;
}

void setup() {
  Serial.begin(9600);
  pinMode(BUZZER, OUTPUT);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pixels.begin();
  pixels.show();
}

void loop() {
  distance = readDistanceCm();
  Serial.print("distance (cm): ");
  Serial.println(distance);
  if (distance < 30) {
    pixels.setPixelColor(0, pixels.Color(255, 0, 0));
    pixels.show();
    tone(BUZZER, 1000);
    delay(100);
    noTone(BUZZER);
  } else if (distance < 60) {
    pixels.setPixelColor(0, pixels.Color(255, 120, 0));
    pixels.show();
  } else {
    pixels.setPixelColor(0, pixels.Color(0, 255, 0));
    pixels.show();
  }
  delay(200);
}

